def chunks(items, size):
    chunk = []
    for item in items:
        chunk.append(item)
        if len(chunk) == size:
            yield chunk
            chunk = []
    if chunk:
        yield chunk


def running_total(numbers):
    total = 0
    for n in numbers:
        total += n
        yield total


def primes():
    found = []
    n = 2
    while True:
        if all(n % p for p in found if p * p <= n):
            found.append(n)
            yield n
        n += 1


def take(n, iterable):
    if n <= 0:
        return
    for i, item in enumerate(iterable, start=1):
        yield item
        if i == n:
            return

